"""Candidate suggestions, generated by rules from the portfolio facts and the client's profile.

The Rivet Analyst chooses 2 or 3 of these candidates and explains each one with the XP macro
scenario; it may not invent a movement. In tests, letting the model decide the movements freely
led to suggestions that added to the month's biggest losers or to positions already concentrated,
and the reviewer itself misjudged suitability (e.g. "Tesouro Selic is not for an aggressive
client"). Rules are predictable, auditable and are the starting point of the premises to be
defined with a certified specialist.

Each candidate: id, type ("opportunity" | "protection"), action_pt (what to consider doing) and
basis_pt (the objective reason). Amounts come already formatted from the facts.
"""

from __future__ import annotations

from core.briefing import brl, pct
from core.models import FIXED_INCOME, STOCKS, Portfolio

STOCK_DRAWDOWN_PCT = -5.0         # stocks fell more than this in the month...
STOCK_HEAVY_WEIGHT_PCT = 40.0     # ...while being more than this share of the portfolio
EQUITY_GAP_PP = 5.0               # equity below the profile benchmark's Ibovespa weight by more than this

# Opportunities taken from the macro scenario, by profile: only instruments every client of the
# profile may hold. The Analyst uses one only if the macro digest supports it.
MACRO_CANDIDATES = {
    "conservative": [
        ("macro:inflation_linked", "Incluir títulos atrelados à inflação para diversificar os indexadores da "
                                   "renda fixa"),
    ],
    "moderate": [
        ("macro:inflation_linked", "Incluir títulos atrelados à inflação para diversificar os indexadores da "
                                   "renda fixa"),
        ("macro:multimarket", "Incluir fundos multimercado diversificados"),
    ],
    "aggressive": [
        ("macro:inflation_linked", "Incluir títulos atrelados à inflação para diversificar os indexadores da "
                                   "carteira"),
        ("macro:equity_fund", "Usar fundos de ações diversificados, em vez de ampliar posições individuais"),
    ],
}


def candidates(portfolio: Portfolio, report: dict, facts: dict, profile: str,
               benchmark_weights: dict[str, float] | None = None) -> list[dict]:
    equity = portfolio.total_equity
    by_name = {p.name: p for p in portfolio.positions}
    out: list[dict] = []

    for fact in facts["facts"]:
        fid = fact["id"]
        if fid == "idle_cash":
            out.append({"id": fid, "type": "opportunity",
                        "action_pt": f"Aplicar parte do saldo parado em conta ({brl(portfolio.cash_available)}) em "
                                     "renda fixa pós-fixada de liquidez diária, mantendo a reserva que o perfil pede",
                        "basis_pt": f"{fact['fact']}; custo de oportunidade no mês de {fact['opportunity_cost_month']}"})
        elif fid.startswith("matured:"):
            p = by_name[fid.split(":", 1)[1]]
            out.append({"id": fid, "type": "opportunity",
                        "action_pt": f"Reinvestir os {brl(p.market_value)} do {p.name}, que já venceu, em renda fixa "
                                     "compatível com o perfil",
                        "basis_pt": fact["fact"]})
        elif fid.startswith("concentration:"):
            p = by_name[fid.split(":", 1)[1]]
            share = pct(p.market_value / equity * 100, signed=False)
            if p.asset_class == FIXED_INCOME:
                action = (f"Não concentrar novos aportes no {p.name} ({share} do patrimônio) e, no vencimento, "
                          "distribuir o valor entre outros emissores")
            else:
                action = (f"Reduzir aos poucos a posição em {p.name} ({share} do patrimônio), distribuindo entre "
                          "outros ativos da mesma classe")
            out.append({"id": fid, "type": "protection", "action_pt": action, "basis_pt": fact["fact"]})
        elif fid == "no_fixed_income":
            out.append({"id": fid, "type": "protection",
                        "action_pt": "Criar uma parcela de renda fixa pós-fixada como proteção e liquidez",
                        "basis_pt": fact["fact"]})

    stocks = next((c for c in report["classes"] if c["asset_class"] == STOCKS), None)
    if stocks and stocks["monthly_return_pct"] < STOCK_DRAWDOWN_PCT and stocks["weight_pct"] > STOCK_HEAVY_WEIGHT_PCT:
        out.append({"id": "stocks_drawdown", "type": "protection",
                    "action_pt": "Direcionar novos aportes para outras classes, em vez de ampliar as ações, "
                                 "sem vender por causa da queda do mês",
                    "basis_pt": f"Ações são {pct(stocks['weight_pct'], signed=False)} da carteira e renderam "
                                f"{pct(stocks['monthly_return_pct'])} no mês"})

    # Equity well below the profile's neutral mix: discuss adding to positions the client already has.
    equity_rows = [p for p in report["positions"] if p["asset_class"] == STOCKS or p["sub_class"] == "equity_fund"]
    equity_pct = sum(p["weight_pct"] for p in equity_rows)
    neutral_pct = (benchmark_weights or {}).get("IBOV", 0) * 100
    if equity_rows and neutral_pct - equity_pct > EQUITY_GAP_PP:
        best = sorted(equity_rows, key=lambda p: -p["contribution_brl"])[:2]
        out.append({"id": "equity_below_profile", "type": "opportunity",
                    "action_pt": "Discutir a possibilidade de aumentar posições de renda variável que você já tem, "
                                 f"como {' e '.join(p['name'] for p in best)}, dentro do perfil",
                    "basis_pt": f"Renda variável é {pct(equity_pct, signed=False)} da carteira; a carteira de "
                                f"referência do perfil usa {pct(neutral_pct, signed=False)} em Ibovespa"})

    for cid, action in MACRO_CANDIDATES.get(profile, []):
        out.append({"id": cid, "type": "opportunity", "action_pt": action,
                    "basis_pt": "Usar somente se o resumo macro da XP for favorável a essa classe"})
    return out
